import argparse,json,hashlib
from pathlib import Path
import numpy as np
p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);a=p.parse_args();root=a.output.resolve();r=np.load(root/'rigid.npz');q=r['sand'];b=r['ball'];t=r['t'];h=hashlib.sha256((root/'rigid.npz').read_bytes()).hexdigest();checks={'finite':bool(np.isfinite(q).all() and np.isfinite(b).all()),'max_timestamp_error_s':float(abs(t-np.arange(len(t))/24).max()),'max_ball_displacement_per_frame_m':float(np.linalg.norm(np.diff(b,axis=0),axis=1).max()),'sand_precontact_mean_displacement_m':float(np.linalg.norm(q[40]-q[0],axis=1).mean()),'sand_final_samples_displaced_gt_2cm':int((np.linalg.norm(q[-1]-q[0],axis=1)>.02).sum()),'sand_final_displacement_p99_m':float(np.percentile(np.linalg.norm(q[-1]-q[0],axis=1),99))}
checks['event_order']=json.loads((root/'rigid.json').read_text())['events'];events=list(checks['event_order'].values());assert all(x is not None for x in events) and events==sorted(events)
for kind in ['cloth','liquid']:
 meta=json.loads((root/kind/'simulation.json').read_text());assert meta['source_trajectory_sha256']==h
sm=json.loads((root/'smoke/simulation.json').read_text());sm['source_trajectory_sha256']=h;(root/'smoke/simulation.json').write_text(json.dumps(sm,indent=2))
metadata={'solvers':{'rigid_sand':'Newton 1.7 / XPBD + implicit MPM','cloth':'BS-Cloth / B-spline FEM + IPC','liquid':'SPlisHSPlasH 2.19.1 / DFSPH + splashsurf','smoke':'Mantaflow'},'clock':{'fps':24,'frames':124},'source_trajectory_sha256':h,'checks':checks,'coupling':'Rigid-sand impulse exchange is bidirectional. Newton trajectory drives cloth, smoke and water one-way. Sand is not a fluid boundary.','rendering':'Blender 4.5.3 Cycles CUDA / fixed camera; foreground rail and tank wall omitted for visibility; physical colliders retained.','limitations':'No full bidirectional multiphysics, convergence or material calibration. BS-Cloth uses 12x12 controls, 37x37 contact samples and 5 steps per frame; evaluated surface adds no DOFs.'};(root/'harness.json').write_text(json.dumps(metadata,indent=2));print(metadata,flush=True)
